<script setup>
import {ref} from 'vue';import {Pencil} from 'lucide-vue-next';
const props=defineProps({modelValue:String,label:String});const emit=defineEmits(['apply','save']);const draft=ref('#485766'),panel=ref(null);
function opened(){if(!panel.value?.open)draft.value=/^#[0-9a-f]{6}$/i.test(props.modelValue)?props.modelValue:'#d0aa6f';}
function use(save){emit(save?'save':'apply',draft.value);panel.value.open=false;}
</script>
<template><details ref="panel" class="studio-color-picker"><summary @click="opened" class="custom-swatch" :aria-label="`Custom ${label}`" :title="`Choose ${label}`"><Pencil :size="14"/></summary><section :aria-label="`${label} color picker`"><label><span>{{label}}</span><input type="color" :aria-label="`Choose ${label} shade`" v-model="draft"/></label><span class="color-value">{{draft}}</span><footer><button type="button" @click="use(false)">Apply Colour</button><button type="button" @click="use(true)">Save Colour as Default</button></footer></section></details></template>
<style scoped>
.studio-color-picker{display:inline-block;position:relative}.studio-color-picker summary{list-style:none;cursor:pointer}.studio-color-picker summary::-webkit-details-marker{display:none}.studio-color-picker[open]{z-index:40}.studio-color-picker section{position:absolute;right:0;top:calc(100% + 8px);width:270px;max-width:75vw;padding:15px;background:#122d3d;border:1px solid #8caabd;box-shadow:0 12px 35px #0009;border-radius:8px;display:grid;gap:10px}.studio-color-picker label{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px}.studio-color-picker input{width:38px;height:38px;min-width:38px;max-width:38px;flex:none;cursor:pointer;border:0;padding:0;background:transparent}.studio-color-picker footer{display:grid;grid-template-columns:1fr 1fr;gap:8px}.studio-color-picker footer button{width:auto;height:auto;min-height:44px;border-radius:4px;padding:8px;color:#e3f1fa;font-size:11px;line-height:1.35;background:#254b61;border:1px solid #668c9f}.color-value{font-size:12px;font-family:var(--mono)}
.studio-color-picker input::-webkit-color-swatch-wrapper{padding:3px}.studio-color-picker input::-webkit-color-swatch{border:1px solid #8caabd;border-radius:6px}.studio-color-picker input::-moz-color-swatch{border:1px solid #8caabd;border-radius:6px}</style>
